package main
import ("log";"net/http";"os")
func main(){p:=os.Getenv("PORT");if p==""{p="10000"};http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");w.Write([]byte(html))});log.Println(p);http.ListenAndServe(":"+p,nil)}
const html=
"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>U</title><script src='https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js'></script><style>body{margin:0;font-family:system-ui;background:#f1f5f1}header{background:#1a6d2f;color:#fff;padding:10px;text-align:center;font-weight:900}.card{background:#fff;margin:8px;border-radius:8px;padding:8px}.top3{display:flex;gap:4px}.top3 div{flex:1;padding:8px;border-radius:6px;color:#fff;text-align:center;font-weight:900;font-size:12px}.g{background:#2e7d32}.r{background:#c62828}.b{background:#1565c0}select,input,button{width:100%;padding:7px;margin:2px 0;border-radius:5px;border:1px solid #bbb}button{background:#1a6d2f;color:#fff;border:0}</style><header>Uwashusema Mahida<br><small>Riba: Ada 30% na Marejesho 30%</small></header><div class=card><div style='display:flex;gap:4px'><select id=m><option value=11>Nov<option value=12>Des</select><input id=y type=number value=2026><button onclick=R() style='width:60px'>Sawa</button></div><div class=top3 style='margin-top:6px'><div class=g>MAPATO<br><span id=a>0</span></div><div class=r>MATUMIZI<br><span id=b>0</span></div><div class=b>SALIO<br><span id=c>0</span></div></div></div><div class=card><b>Wanachama <button onclick=W() style='width:auto;float:right'>+ Mpya</button></b><div id=wl></div></div><div class=card><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada<option value=marejesho>Marejesho<option value=faini_ada>Riba Ada<option value=faini_marejesho>Riba Rejesho<option value=mkopo_toka>Mkopo</select><input id=k type=number placeholder=Kiasi><button onclick=M()>Hifadhi</button><div id=ca style=color:green></div></div><div class=card><button onclick=E() style='background:#1565c0'>Pakua Excel</button></div><script>D=JSON.parse(localStorage.getItem('v')||'null')||{w:[],m:[]};function S(){localStorage.setItem('v',JSON.stringify(D));R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=sw.value;a=sa.value;k=+k.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}k.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','marejesho','faini_ada','faini_marejesho','fomu'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='<small>Hakuna</small>';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\" style=width:auto>X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'})}kEl=document.getElementById('k');sa.onchange=()=>{k=+kEl.value;ca.innerHTML=sa.value=='mkopo_toka'&&k>0?'Fomu AUTO='+Math.round(k*0.05)+' (1.5M=75k)':''};kEl.oninput=()=>sa.onchange();function E(){mm=+m.value;yy=+y.value;all=D.m.filter(x=>x.mm==mm&&x.yy==yy);if(!all.length)return alert('Hakuna');ada=[['Jina','Ada','Riba']];mk=[['Jina','Mkopo','Fomu','Rejesho','Riba']];hs=[['Jina','Hisa']];am={};amR={};dm={};hm={};D.w.forEach(x=>{am[x.j]=0;amR[x.j]=0;dm[x.j]={c:0,f:0,r:0,fr:0};hm[x.j]=0});all.forEach(t=>{if(t.a=='ada')am[t.w]+=t.k;if(t.a=='faini_ada')amR[t.w]+=t.k;if(t.a=='mkopo_toka')dm[t.w].c+=t.k;if(t.a=='fomu')dm[t.w].f+=t.k;if(t.a=='marejesho')dm[t.w].r+=t.k;if(t.a=='faini_marejesho')dm[t.w].fr+=t.k;if(t.a=='hisa')hm[t.w]+=t.k});for(j in am)ada.push([j,am[j],amR[j]]);for(j in dm){d=dm[j];if(d.c>0)mk.push([j,d.c,d.f,d.r,d.fr])}for(j in hm)hs.push([j,hm[j]]);wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(ada),'Ada');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(mk),'Mikopo');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(hs),'Hisa');XLSX.writeFile(wb,'Uwashusema.xlsx')}m.value=11;R();</script>"
